import { Component, Element, Host, Prop, State, h } from "@stencil/core";

/**
 * @since 0.0.6
 * @status beta
 *
 */
@Component({
	tag: "hbr-nav-group",
	styleUrl: "nav-group.scss",
	shadow: true,
})
export class HbrNavGroup {
	@Element() host: HTMLHbrNavGroupElement;

	private labelRef: HTMLSpanElement;
	private labelSlotRef: HTMLSlotElement;

	@State() labelTruncated = false;

	@State() labelText = "";

	/** collapsed state in side nav */
	@Prop({ reflect: true }) collapsed = false;

	private getAssignedLabelElement = () => {
		return this.labelSlotRef?.assignedElements({ flatten: true })?.[0] as
			| HTMLElement
			| undefined;
	};

	private syncLabelText = () => {
		this.labelText = this.labelSlotRef
			?.assignedNodes({ flatten: true })
			.map((node) => node.textContent ?? "")
			.join("")
			.trim();
	};

	private syncLabelOverflow = () => {
		const assignedLabelElement = this.getAssignedLabelElement();
		const overflowElement = assignedLabelElement ?? this.labelRef;
		this.labelTruncated = overflowElement
			? overflowElement.scrollWidth > overflowElement.clientWidth
			: false;
	};

	private handleLabelSlotChange = () => {
		this.syncLabelText();
		this.syncLabelOverflow();
	};

	componentDidLoad() {
		this.syncLabelText();
		this.syncLabelOverflow();
	}

	render() {
		return (
			<Host role="group">
				<span
					ref={(el) => {
						this.labelRef = el;
					}}
					class={{
						"nav-label": true,
						"nav-label--collapsed": this.collapsed,
					}}
					part="label"
				>
					<slot
						name="label"
						ref={(el) => {
							this.labelSlotRef = el as HTMLSlotElement;
						}}
						onSlotchange={this.handleLabelSlotChange}
					/>
				</span>

				<slot />
				<hbr-tooltip
					content={this.labelText}
					anchor={this.labelRef}
					disabled={!this.labelTruncated}
					hoist
					placement="right-start"
				/>
				<hbr-resize-observer
					anchor={this.host}
					subscriber={this.labelRef}
					onHbr-resize={this.syncLabelOverflow}
				/>
			</Host>
		);
	}
}
